# All three matching pairs appear seated and both grippers are open. I will return both arms toward their saved starting joints and stop on official completion.
obs = get_observation()
return_start = {k: np.array(v) for k,v in obs['state'].items() if k.endswith('joint_state')}
for i in range(120):
    if control['halted'] or control['remaining'] <= 0:
        break
    t = min(1.0, (i+1)/85.0)
    action = {'left_arm_joint_state':return_start['left_arm_joint_state']*(1-t)+origin['left_arm_joint_state']*t,
              'right_arm_joint_state':return_start['right_arm_joint_state']*(1-t)+origin['right_arm_joint_state']*t,
              'left_ee_joint_state':[1], 'right_ee_joint_state':[1]}
    obs, reward, terminated, truncated, info = step(action)
    control['remaining'] -= 1
    control['halted'] = terminated or truncated
    if control['halted']:
        print('terminal', reward, terminated, truncated, info)
print('remaining',control['remaining'],'state',obs['state'])

